Here is a JavaScript function that flattens a nested array using recursion.

```javascript
/**
 * Flattens a nested array into a single-level array.
 *
 * @param {Array<any>} arr The nested array to flatten.
 * @returns {Array<any>} A new, one-dimensional array containing all elements.
 */
function flattenArray(arr) {
  let flattened = [];

  for (const element of arr) {
    if (Array.isArray(element)) {
      // If the element is an array, recursively flatten it and concatenate the result
      flattened = flattened.concat(flattenArray(element));
    } else {
      // If the element is not an array, just push it to the result
      flattened.push(element);
    }
  }

  return flattened;
}

// --- Examples ---

const nestedArray1 = [1, [2, 3], [4, [5, 6]], 7];
const flatArray1 = flattenArray(nestedArray1);
console.log("Example 1 Input:", JSON.stringify(nestedArray1));
console.log("Example 1 Output:", flatArray1); // Output: [1, 2, 3, 4, 5, 6, 7]

const nestedArray2 = [1, [2, [3, [4]]], 5];
const flatArray2 = flattenArray(nestedArray2);
console.log("\nExample 2 Input:", JSON.stringify(nestedArray2));
console.log("Example 2 Output:", flatArray2); // Output: [1, 2, 3, 4, 5]

const flatArray3 = flattenArray([1, 2, 3]);
console.log("\nExample 3 Input:", JSON.stringify([1, 2, 3]));
console.log("Example 3 Output:", flatArray3); // Output: [1, 2, 3]
```

