Here is a JavaScript function that formats a number as a currency string.

This function takes a number and a currency code (like 'USD' or 'EUR') and returns a formatted string. It uses `Intl.NumberFormat` for robust, locale-aware formatting.

```javascript
/**
 * Formats a number as a currency string based on the specified currency code and locale.
 *
 * @param {number} amount The number to format.
 * @param {string} currencyCode The ISO 4217 currency code (e.g., 'USD', 'EUR', 'JPY').
 * @param {string} locale The locale to use for formatting (e.g., 'en-US', 'de-DE').
 * @returns {string} The formatted currency string.
 * @throws {Error} If the amount is not a valid number or if Intl.NumberFormat is unavailable.
 */
function formatCurrency(amount, currencyCode, locale = 'en-US') {
    if (typeof amount !== 'number' || isNaN(amount)) {
        throw new Error("Invalid amount provided. Amount must be a number.");
    }
    if (typeof currencyCode !== 'string' || currencyCode.length === 0) {
        throw new Error("Invalid currency code provided. Currency code must be a non-empty string.");
    }

    try {
        // Use Intl.NumberFormat for reliable, locale-aware currency formatting
        const formatter = new Intl.NumberFormat(locale, {
            style: 'currency',
            currency: currencyCode,
        });

        return formatter.format(amount);
    } catch (error) {
        console.error("Error during currency formatting:", error);
        throw new Error(`Failed to format currency: ${error.message}`);
    }
}

// --- Examples ---

// 1. US Dollar formatting
const amountUSD = 12345.678;
try {
    const formattedUSD = formatCurrency(amountUSD, 'USD', 'en-US');
    console.log(`USD Example (en-US): ${formattedUSD}`); // Output: $12,345.68
} catch (e) {
    console.error(e.message);
}

// 2. Euro formatting (German locale)
const amountEUR = 9876.54;
try {
    const formattedEUR = formatCurrency(amountEUR, 'EUR', 'de-DE');
    console.log(`EUR Example (de-DE): ${formattedEUR}`); // Output: 9.876,54 €
} catch (e) {
