/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let lastExecTime = 0;

  return function(...args) {
    const context = this;
    const now = Date.now();

    // If it has been less than 'wait' milliseconds since the last execution,
    // we check if we need to schedule a call.
    if (now - lastExecTime < wait) {
      // If a timeout is not already scheduled, we store the latest arguments
      // and set a timeout to execute the function after the wait period.
      if (!timeout) {
        timeout = setTimeout(() => {
          lastExecTime = Date.now();
          timeout = null;
          // Execute the function with the latest context and arguments
          func.apply(context, lastArgs);
        }, wait - (now - lastExecTime));
      }
      // Update the arguments and context for the next potential call
      lastArgs = args;
      lastThis = context;
      return;
    } else {
      // If enough time has passed, execute immediately and update the time.
      lastExecTime = now;
      func.apply(context, args);
    }
  };
}

