Here is a TypeScript function that groups an array of objects by a specified key.

This solution uses the `reduce` method for an efficient and functional approach.

```typescript
/**
 * Defines the structure for the objects in the array.
 * You can change this interface to match your actual data structure.
 */
interface DataItem {
  id: number;
  category: string;
  value: number;
}

/**
 * Groups an array of objects by the value of a specified key.
 *
 * @param arr The array of objects to group.
 * @param key The key in the objects to group by.
 * @returns A Map where keys are the unique values of the grouping key,
 *          and values are arrays of objects belonging to that group.
 */
function groupArrayBy<T extends Record<string, any>, K extends keyof T>(
  arr: T[],
  key: K
): Map<T[K], T[]> {
  return arr.reduce((acc: Map<T[K], T[]>, currentItem: T): Map<T[K], T[]> => {
    const groupKey = currentItem[key];

    // Check if the accumulator already has an array for this key
    if (!acc.has(groupKey)) {
      // If not, initialize a new array for this key
      acc.set(groupKey, []);
    }

    // Push the current item into the corresponding group array
    acc.get(groupKey)!.push(currentItem);

    return acc;
  }, new Map<T[K], T[]>());
}

// --- Example Usage ---

const data: DataItem[] = [
  { id: 1, category: 'A', value: 10 },
  { id: 2, category: 'B', value: 20 },
  { id: 3, category: 'A', value: 15 },
  { id: 4, category: 'C', value: 30 },
  { id: 5, category: 'B', value: 25 },
];

// 1. Group by 'category'
const groupedByCategory = groupArrayBy(data, 'category');

console.log("--- Grouped by Category ---");
groupedByCategory.forEach((group, category) => {
  console.log(`Category: ${category}`);
  console.log("Items:", group);
});

console.log("\n" + "=".repeat(30) + "\n");

