console.log("--- Grouped by ID ---");
groupedById.forEach((group, id) => {
  console.log(`ID: ${id}`);
  console.log("Item:", group[0]); // Since ID is unique, the group will have one item
});
```

### Explanation:

1.  **Generics (`<T extends Record<string, any>, K extends keyof T>`):**
    *   `T`: Represents the type of the objects in the input array (e.g., `DataItem`).
    *   `K`: Represents the key we want to group by. `keyof T` ensures that `key` is a valid property name of type `T`.
2.  **Return Type (`Map<T[K], T[]>`):**
    *   The function returns a `Map`.

Here is a TypeScript function that computes the median of an array of numbers.

The median is the middle value of a dataset when it is sorted. If the dataset has an odd number of elements, the median is the middle element. If it has an even number of elements, the median is the average of the two middle elements.

```typescript
/**
 * Computes the median of an array of numbers.
 *
 * @param numbers An array of numbers.
 * @returns The median of the array, or null if the array is empty.
 */
function findMedian(numbers: number[]): number | null {
    if (numbers.length === 0) {
        return null; // Return null for an empty array
    }

    // 1. Sort the array numerically
    const sortedNumbers: number[] = [...numbers].sort((a, b) => a - b);
    const length: number = sortedNumbers.length;

    // 2. Check if the length is odd or even
    if (length % 2 === 1) {
        // Odd length: The median is the middle element
        const middleIndex: number = Math.floor(length / 2);
        return sortedNumbers[middleIndex];
    } else {
        // Even length: The median is the average of the two middle elements
        const upperMiddleIndex: number = length / 2;
        const lowerMiddleIndex: number = upperMiddleIndex - 1;

        const middle1: number = sortedNumbers[lowerMiddleIndex];
        const middle2: number = sortedNumbers[upperMiddleIndex];

        return (middle1 + middle2) / 2;
    }
}

// --- Examples ---

// Example 1: Odd number of elements
const oddArray: number[] = [3, 1, 4, 1, 5, 9, 2];
// Sorted: [1, 1, 2, 3, 4, 5, 9]. Median is 3.
const medianOdd = findMedian(oddArray);
console.log(`Median of [${oddArray}]: ${medianOdd}`); // Output: 3

// Example 2: Even number of elements
const evenArray: number[] = [1, 2, 3, 4];
// Sorted: [1, 2, 3, 4]. Median is (2 + 3) / 2 = 2.5
const medianEven = findMedian(evenArray);
console.log(`Median of [${evenArray}]: ${medianEven}`); // Output: 2.5

// Example 3: Empty array
const emptyArray: number[] = [];
const medianEmpty = findMedian(emptyArray);
console.log(`Median of []: ${medianEmpty}`); // Output: null

// Example 4: Array with negative numbers and duplicates
const mixedArray: number[] = [-5, 10, 0, -5, 2];
// Sorted: [-5, -5, 0, 2, 10]. Median is 0.
const medianMixed = findMedian(mixedArray);
console.log(`Median of [${mixedArray}]: ${medianMixed}`); // Output: 0
```

