Here is a Rust function that removes duplicates from a `Vec<T>`.

To remove duplicates efficiently, we can leverage a `HashSet` to keep track of the elements we have already seen.

```rust
use std::collections::HashSet;

/// Removes duplicate elements from a vector, preserving the order of first appearance.
///
/// # Arguments
///
/// * `vec` - A mutable reference to the vector to deduplicate.
///
/// # Type Parameters
///
/// * `T` - The type of elements in the vector, which must implement the `Eq` and `Hash` traits
///         to be stored in a `HashSet`.
///
/// # Examples
///
/// ```
/// let mut numbers = vec![1, 2, 2, 3, 4, 4, 5];
/// remove_duplicates(&mut numbers);
/// assert_eq!(numbers, vec![1, 2, 3, 4, 5]);
///
/// let mut strings = vec!["apple", "banana", "apple", "cherry"];
/// remove_duplicates(&mut strings);
/// assert_eq!(strings, vec!["apple", "banana", "cherry"]);
/// ```
pub fn remove_duplicates<T: Eq + std::hash::Hash>(vec: &mut Vec<T>) {
    let mut seen: HashSet<T> = HashSet::new();
    let mut result: Vec<T> = Vec::new();

    for item in vec.drain(..) {
        if seen.insert(item) {
            // If insert returns true, the item was not present before, so we keep it.
            result.push(item);
        }
    }

    // Replace the original vector content with the unique elements.
    *vec = result;
}

fn main() {
    // Example 1: Integers
    let mut numbers = vec![1, 2, 2, 3, 4, 4, 5, 1];
    println!("Original numbers: {:?}", numbers);
    remove_duplicates(&mut numbers);
    println!("Numbers after deduplication: {:?}", numbers);
    // Expected: [1, 2, 3, 4, 5]

    println!("--------------------");

    // Example 2: Strings
    let mut strings = vec!["apple", "banana", "apple", "cherry", "banana", "date"];
    println!("Original strings: {:?}", strings);
    remove_duplicates(&mut strings);
    println!("Strings after deduplication: {:?}", strings);
    // Expected: ["apple", "banana", "cherry", "date"]
}
